class ClientCertificateMTLS1(BaseModel):
    """
    mTLS credentials, named as the providers name them: Aiven's access key / access certificate / CA certificate, Confluent's client key / client certificate. Paste each PEM block whole, including its BEGIN and END lines.
    """

    model_config = ConfigDict(
        extra='forbid',
    )
    access_key: str = Field(
        ...,
        description='PEM-encoded client private key — the block starting with -----BEGIN PRIVATE KEY----- (Aiven: service.key)',
    )
    access_certificate: str = Field(
        ...,
        description='PEM-encoded client certificate — the block starting with -----BEGIN CERTIFICATE----- (Aiven: service.cert)',
    )
    ca_certificate: str | None = Field(
        None,
        description="PEM-encoded CA certificate used to verify the broker's TLS certificate — the provider's ca.pem. Required for private or self-signed CAs; leave empty to trust the system CA bundle.",
    )


