class DropboxOAuthRefreshTokenRecommended(BaseModel):
    """
    Recommended. An OAuth app key and secret plus a refresh token, which never expires — the client mints a fresh access token on every run. Obtain the refresh token once with `classifyre dropbox-auth --app-key <key> --app-secret <secret>`; it prints a URL you open in your own browser and exchanges the code it gives you.
    """

    model_config = ConfigDict(
        extra='forbid',
    )
    auth_method: Literal['oauth']
    app_key: str = Field(
        ..., description='Dropbox app key (App Console → Settings → App key)'
    )


class DropboxOAuthWithPKCENoAppSecret(BaseModel):
    """
    Same as the OAuth refresh token flow but for apps that hold no secret: the authorization is proved with PKCE, so only the app key is needed to refresh. Obtain the refresh token with `classifyre dropbox-auth --app-key <key> --pkce`.
    """

    model_config = ConfigDict(
        extra='forbid',
    )
    auth_method: Literal['oauth_pkce']
    app_key: str = Field(
        ..., description='Dropbox app key (App Console → Settings → App key)'
    )


class DropboxAccessTokenShortLivedTestingOnly(BaseModel):
    """
    Testing only. The token generated by the App Console button is short-lived and stops working about four hours later with `invalid_access_token`, so scheduled scans will fail. Use one of the refresh-token methods for anything recurring.
    """

    model_config = ConfigDict(
        extra='forbid',
    )
    auth_method: Literal['access_token']


